import React, { useEffect, useState } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:8080');

interface ChatComponentProps {
    userId: string;
    agencyId: string;
}

const ChatComponent: React.FC<ChatComponentProps> = ({ userId, agencyId }) => {
    const [messages, setMessages] = useState<{ senderId: string; messageContent: string }[]>([]);
    const [message, setMessage] = useState('');

    useEffect(() => {
        const room = `${userId}_${agencyId}`;
        socket.emit('join_room', room);

        socket.on('receive_message', (data) => {
            setMessages((prevMessages) => [...prevMessages, data]);
        });

        return () => {
            socket.emit('leave_room', room);
        };
    }, [userId, agencyId]);

    const sendMessage = () => {
        if (message.trim()) {
            const newMessage = { senderId: userId, receiverId: agencyId, messageContent: message };
            socket.emit('send_message', { ...newMessage, room: `${userId}_${agencyId}` });
            setMessages((prevMessages) => [...prevMessages, newMessage]);
            setMessage('');
        }
    };

    return (
        <div>
            <div>
                {messages.map((msg, index) => (
                    <div key={index}>
                        <strong>{msg.senderId === userId ? 'You' : 'Agency'}:</strong> {msg.messageContent}
                    </div>
                ))}
            </div>
            <input
                type="text"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Type a message"
            />
            <button onClick={sendMessage}>Send</button>
        </div>
    );
};

export default ChatComponent;
